    # Split the input string into a list of letters
    letters = test.split()

    # Dictionary to count occurrences of each letter
    count_dict = {}

    # Count each letter
    for letter in letters:
        if letter in count_dict:
            count_dict[letter] += 1
        else:
            count_dict[letter] = 1

    # Determine the maximum count value
    if not count_dict:
        return {}

    max_count = max(count_dict.values())

    # Create a dictionary of letters with the maximum count
    result = {letter: count for letter, count in count_dict.items() if count == max_count}

    return result

