def split_words(txt):
    # Step 1: Check for whitespace and split if found
    if ' ' in txt:
        return txt.split()

    # Step 2: Check for commas and split if found
    elif ',' in txt:
        return txt.split(',')

    # Step 3: Count lowercase letters with odd order in the alphabet
    else:
        odd_order_count = 0
        for char in txt:
            if char.islower():
                # Calculate the order of the character in the alphabet
                order = ord(char) - ord('a')
                # Check if the order is odd
                if order % 2 == 1:
                    odd_order_count += 1
        return odd_order_count

